def earliestSecondToMarkIndices(nums, changeIndices):
    n = len(nums)
    m = len(changeIndices)

    def feasible(S):
        # Last second in [1, S] at which each (1-based) index can be marked.
        last = {}
        for sec in range(1, S + 1):
            last[changeIndices[sec - 1]] = sec
        for i in range(1, n + 1):
            if i not in last:
                return False
        # The second at which we mark each index (its last occurrence).
        mark_at = {}
        for i in range(1, n + 1):
            mark_at[last[i]] = i
        # Sweep seconds; free seconds accumulate as decrement capacity. When we
        # reach an index's marking second, we must already have >= nums[i]
        # decrement-seconds banked (and this second is spent on the mark itself).
        available = 0
        for sec in range(1, S + 1):
            if sec in mark_at:
                need = nums[mark_at[sec] - 1]
                if available < need:
                    return False
                available -= need
            else:
                available += 1
        return True

    lo, hi, ans = 1, m, -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans
